# Fill COMPREPLY with safely quoted local branches and target 1 matching the typed prefix.
# Decode only quoting syntax in the prefix; never evaluate shell expansions.
# Escape each candidate for the active single/double/unquoted context.
_git_gtr_complete_targets() {
  local raw_prefix="$1" prefix="" quote="" before_quote="" escaped=0 char i
  local branch branches quoted fragment ansi=0 dollar=0 was_dollar
  local single_escape="'\\''" ansi_escape="\\'"
  local dollar_escape='\$' tick_escape='\`' double_escape='\"' history_escape='"\!"'
  for ((i=0; i<${#raw_prefix}; i++)); do
    char="${raw_prefix:i:1}"
    was_dollar="$dollar"
    dollar=0
    if [ "$escaped" -eq 1 ]; then
      # Double quotes only consume backslashes before these shell characters.
      if [ "$quote" = '"' ]; then
        case "$char" in
          '"'|'$'|'`'|'\') ;;
          *) prefix+='\' ;;
        esac
      fi
      prefix+="$char"
      escaped=0
    elif [ "$char" = "$quote" ]; then
      quote=""
      before_quote=""
      ansi=0
    elif [ "$quote" = "'" ]; then
      if [ "$ansi" -eq 1 ] && [ "$char" = '\' ]; then
        escaped=1
      else
        prefix+="$char"
      fi
    else
      case "$char" in
        '\') escaped=1 ;;
        "'"|'"')
          if [ -z "$quote" ]; then
            if [ "$char" = "'" ] && [ "$was_dollar" -eq 1 ]; then
              ansi=1
              prefix="${prefix%?}"
            fi
            quote="$char"
            before_quote="$prefix"
          else
            prefix+="$char"
          fi
          ;;
        '$') prefix+="$char"; [ -n "$quote" ] || dollar=1 ;;
        *) prefix+="$char" ;;
      esac
    fi
  done
  branches=$(git branch --no-column --format='%(refname:short)' 2>/dev/null || true)
  COMPREPLY=()
  # compgen -W evaluates its word list; treat branch names as literal data instead.
  while IFS= read -r branch; do
    printf -v quoted '%q' "$branch"
    if [[ -n "$branch" && ( "$branch" == "$prefix"* || "$quoted" == "$raw_prefix"* ) ]]; then
      # Readline retains text before an opening quote within the current word.
      fragment="${branch#"$before_quote"}"
      case "$quote" in
        "'")
          if [ "$ansi" -eq 1 ]; then
            quoted="${fragment//\'/$ansi_escape}"
          else
            quoted="${fragment//\'/$single_escape}"
          fi
          quoted+="'"
          ;;
        '"')
          quoted="${fragment//\$/$dollar_escape}"
          quoted="${quoted//\`/$tick_escape}"
          quoted="${quoted//\"/$double_escape}"
          # Leave double quotes to escape history expansion without adding a backslash.
          quoted="${quoted//!/$history_escape}"
          quoted+='"'
          ;;
      esac
      COMPREPLY+=("$quoted")
    fi
  done <<EOF
1
$branches
EOF
  # Candidates are already escaped; avoid a second quoting pass on newer Bash.
  builtin compopt +o fullquote 2>/dev/null || true
  builtin compopt -o noquote +o filenames 2>/dev/null || true
}

# Dispatch git gtr completion using the current word and arguments from bash-completion.
_git_gtr() {
  local cur prev words cword
  _init_completion || return

  # words array for git subcommand: [git, gtr, <actual_command>, ...]
  # cword is the index of current word being completed

  # If we're completing the first argument after 'git gtr'
  if [ "$cword" -eq 2 ]; then
    COMPREPLY=($(compgen -W "new pr go run copy editor ai rm mv rename ls list clean doctor adapter config completion init trust help version" -- "$cur"))
    return 0
  fi

  local cmd="${words[2]}"

  # Commands that take branch names or '1' for main repo
  case "$cmd" in
    go|run|rm|mv|rename)
      if [ "$cword" -eq 3 ]; then
        # Complete with branch names and special ID '1' for main repo
        _git_gtr_complete_targets "$cur"
      elif [[ "$cur" == -* ]]; then
        case "$cmd" in
          rm)
            COMPREPLY=($(compgen -W "--delete-branch --force --yes" -- "$cur"))
            ;;
          mv|rename)
            COMPREPLY=($(compgen -W "--force --yes" -- "$cur"))
            ;;
        esac
      fi
      ;;
    editor)
      if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "--editor" -- "$cur"))
      elif [ "$prev" = "--editor" ]; then
        COMPREPLY=($(compgen -W "antigravity atom cursor emacs idea nano none nvim pycharm sublime vim vscode webstorm zed" -- "$cur"))
      else
        _git_gtr_complete_targets "$cur"
      fi
      ;;
    ai)
      if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "--ai" -- "$cur"))
      elif [ "$prev" = "--ai" ]; then
        COMPREPLY=($(compgen -W "aider antigravity auggie claude codex continue copilot cursor gemini none opencode" -- "$cur"))
      else
        _git_gtr_complete_targets "$cur"
      fi
      ;;
    ls|list)
      if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "--porcelain" -- "$cur"))
      fi
      ;;
    clean)
      if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "--merged --closed --to --yes -y --dry-run -n --force -f" -- "$cur"))
      fi
      ;;
    copy)
      if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "-n --dry-run -a --all --from" -- "$cur"))
      else
        # Complete with branch names and special ID '1' for main repo
        _git_gtr_complete_targets "$cur"
      fi
      ;;
    new)
      # Complete flags
      if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "--from --from-current --remote --track --no-copy --no-fetch --no-hooks --sparse --no-sparse --force --name --folder --yes --porcelain --editor -e --ai -a" -- "$cur"))
      elif [ "$prev" = "--track" ]; then
        COMPREPLY=($(compgen -W "auto remote local none" -- "$cur"))
      fi
      ;;
    pr)
      if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "--branch -b --repo -R --remote --no-copy --no-hooks --force --name --folder --yes --editor -e --ai -a" -- "$cur"))
      fi
      ;;
    completion)
      # Complete with shell names
      if [ "$cword" -eq 3 ]; then
        COMPREPLY=($(compgen -W "bash zsh fish" -- "$cur"))
      fi
      ;;
    init)
      if [ "$cword" -eq 3 ]; then
        COMPREPLY=($(compgen -W "bash zsh fish" -- "$cur"))
      elif [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "--as" -- "$cur"))
      fi
      ;;
    config)
      # Find action by scanning all config args (handles flexible flag positioning)
      local config_action=""
      local i
      for (( i=3; i < cword; i++ )); do
        case "${words[i]}" in
          list|get|set|add|unset) config_action="${words[i]}" ;;
        esac
      done

      if [ -z "$config_action" ]; then
        # Still need to complete action or scope
        COMPREPLY=($(compgen -W "list get set add unset --local --global --system" -- "$cur"))
      else
        # Have action, complete based on it
        case "$config_action" in
          list|get)
            # Read operations support all scopes including --system
            if [[ "$cur" == -* ]]; then
              COMPREPLY=($(compgen -W "--local --global --system" -- "$cur"))
            else
              COMPREPLY=($(compgen -W "gtr.copy.include gtr.copy.exclude gtr.copy.includeDirs gtr.copy.excludeDirs gtr.hook.postCreate gtr.hook.preRemove gtr.hook.postRemove gtr.hook.postCd gtr.editor.default gtr.editor.workspace gtr.ai.default gtr.worktrees.dir gtr.worktrees.prefix gtr.sparse.inherit gtr.defaultBranch gtr.defaultRemote gtr.provider gtr.ui.color" -- "$cur"))
            fi
            ;;
          set|add|unset)
            # Write operations only support --local and --global (--system requires root)
            if [[ "$cur" == -* ]]; then
              COMPREPLY=($(compgen -W "--local --global" -- "$cur"))
            else
              COMPREPLY=($(compgen -W "gtr.copy.include gtr.copy.exclude gtr.copy.includeDirs gtr.copy.excludeDirs gtr.hook.postCreate gtr.hook.preRemove gtr.hook.postRemove gtr.hook.postCd gtr.editor.default gtr.editor.workspace gtr.ai.default gtr.worktrees.dir gtr.worktrees.prefix gtr.sparse.inherit gtr.defaultBranch gtr.defaultRemote gtr.provider gtr.ui.color" -- "$cur"))
            fi
            ;;
        esac
      fi
